import React, { useState } from 'react';
import './TruckBookingPage.css';

const TruckBookingPage = () => {
  const [pickup, setPickup] = useState('');
  const [drop, setDrop] = useState('');
  const [mobile, setMobile] = useState('');
  const [fare, setFare] = useState(null);
  const [selectedCity, setSelectedCity] = useState("Yamunanagar");
  const [loading, setLoading] = useState(false);

  const handleFareEstimate = async () => {
    if (!pickup || !drop) {
      alert("Please enter both pickup and drop locations");
      return;
    }

    setLoading(true);
    try {
      const response = await fetch(
        `http://localhost:9023/api/tracking/get-fare?from=${pickup}&to=${drop}`
      );
      
      if (!response.ok) throw new Error("Backend error");

      const data = await response.json();
      setFare(data.fare);
      
      // Smooth scroll to fare display
      window.scrollTo({ top: 200, behavior: 'smooth' });

    } catch (error) {
      console.error('Error fetching fare estimate:', error);
      alert("Backend Not Running! Please start your Spring Boot app.");
    } finally {
      setLoading(false);
    }
  };

  const cityData = {
    "Yamunanagar": "https://d3sftlgbtusmnv.cloudfront.net/blog/wp-content/uploads/2024/10/Chaneti-Stupa.jpg",
    "Kurukshetra": "https://thumbs.dreamstime.com/b/sarveshwar-mahadev-temple-brahma-sarovar-kurukshetra-sarveshwar-mahadev-temple-located-brahma-sarovar-kurukshetra-india-428706026.jpg",
    "Chandigarh": "https://dynamic-media-cdn.tripadvisor.com/media/photo-o/09/4c/43/64/the-rock-garden-of-chandigarh.jpg?w=900&h=500&s=1",
    "Karnal": "https://dynamic-media-cdn.tripadvisor.com/media/photo-o/04/7a/f4/f0/noor-mahal.jpg?w=1400&h=1400&s=1",
    "Ambala": "https://static.where-e.com/India/Gurudwara-Panjokhra-Sahib_4a681ef6e540a5634542a6af91fda8e1.jpg",
    "Panchkula": "https://dynamic-media-cdn.tripadvisor.com/media/photo-o/04/58/ae/62/morni-hills.jpg?w=1200&h=-1&s=1"
  };

  return (
    <div className="booking-wrapper">
      <section 
        className="hero-section" 
        style={{ backgroundImage: `linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.7)), url(${cityData[selectedCity]})` }}
      >
        <div className="nav-placeholder">
          <div className="city-badge">
            <span>📍 Serving in {selectedCity}</span>
            <select value={selectedCity} onChange={(e) => setSelectedCity(e.target.value)}>
              {Object.keys(cityData).map(city => <option key={city} value={city}>{city}</option>)}
            </select>
          </div>
        </div>

        <div className="hero-content">
            <h1>Reliable Mini Truck Booking</h1>
            <p>Get instant fare estimates and professional service</p>
        </div>

        {/* Floating Fare Card - Appears when fare is calculated */}
        {fare && (
          <div className="fare-card fade-in">
            <div className="fare-header">Estimated Fare</div>
            <div className="fare-amount">
               <span className="currency">₹</span>{fare}
            </div>
            <div className="fare-footer">Inclusive of taxes & fuel</div>
          </div>
        )}

        <div className="booking-container">
          <div className="input-group">
            <label>Pickup Location</label>
            <input type="text" placeholder="House no, Street..." value={pickup} onChange={(e) => setPickup(e.target.value)} />
          </div>
          <div className="input-divider"></div>
          <div className="input-group">
            <label>Drop Location</label>
            <input type="text" placeholder="Area, Landmark..." value={drop} onChange={(e) => setDrop(e.target.value)} />
          </div>
          <div className="input-divider"></div>
          <div className="input-group">
            <label>Mobile Number</label>
            <input type="tel" placeholder="+91 00000 00000" value={mobile} onChange={(e) => setMobile(e.target.value)} />
          </div>
          <button className="primary-btn" onClick={handleFareEstimate} disabled={loading}>
            {loading ? <div className="spinner"></div> : "Get Fare →"}
          </button>
        </div>
      </section>

      {/* Vehicles & Routes remain same as before but will look better with new CSS */}
    </div>
  );
};

export default TruckBookingPage;
